use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeRegisterCodeUrlAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserAccessTemporalCodeRegisterCodeUrlAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRegisterCodeUrl returns null on a freshly created holder.
     */
    public function testRegisterCodeUrlNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeUrlAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRegisterCodeUrlAssigned());
        $this->assertNull($holder->getRegisterCodeUrl());
    }
}
class ImplWithUserAccessTemporalCodeRegisterCodeUrlAttributeHolderUnitTest
