    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRegisterCodeUrlRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRegisterCodeUrl();
    }
}
